package com.m3.collections;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.Random;
import org.junit.jupiter.api.Test;

/** Generated by M3LeetCodifyRecipe: original bisection kernels of M3WindowRuntime against M3LaneSearch on generated inputs. */
//FLLDCIM: LEETCODIFY — differential proof for M3WindowRuntime
class M3WindowRuntimeLeetCodifyDifferentialTest {
    private static final int SEEDS = 8;
    private static final int MAX_LENGTH = 64;
    private static final int SPAN = 16;

    private static int kernel0(int[] ends, int low, int high, int position) {
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (ends [mid] < position) low = mid + 1;
            else high = mid;
        }
        return low;
    }

    private static void check0(int[] lane, int key) {
        assertEquals(kernel0(lane, 0, lane.length, key), M3LaneSearch.lowerBound(lane, 0, lane.length, key));
    }

    @Test
    void site0_firstEndingAtOrAfter() {
        int[] edge = {Integer.MIN_VALUE, -1, 0, 1, Integer.MAX_VALUE};
        check0(new int[0], 0);
        check0(new int[] {7}, 6);
        check0(new int[] {7}, 7);
        check0(new int[] {7}, 8);
        check0(new int[] {2, 2, 2, 5, 5}, 2);
        check0(new int[] {2, 2, 2, 5, 5}, 3);
        check0(new int[] {2, 2, 2, 5, 5}, 5);
        for (int key : edge) check0(edge, key);
        for (int seed = 0; seed < SEEDS; seed++) {
            Random random = new Random(seed);
            int[] lane = random.ints(random.nextInt(MAX_LENGTH), -SPAN, SPAN).sorted().toArray();
            for (int key = -SPAN - 1; key <= SPAN + 1; key++) check0(lane, key);
        }
    }
}
